var REG={"Θώρακας":"Chest","Ώμος":"Shoulder","Πλάτη":"Back","Αυχένας":"Neck","Κορμός":"Trunk","Κεφαλή":"Head","Βραχίονας":"Upper arm","Αντιβράχιο":"Forearm","Άκρα χείρα":"Hand","Κοιλιά":"Abdomen","Ισχίο":"Hip","Μηρός":"Thigh","Κνήμη":"Lower leg","Άκρο πόδι":"Foot"};
var MUS={"chest":["Pectoralis major","Chest","Brings the arm forward and inward (horizontal adduction), rotates it inward and helps flex the shoulder. The clavicular part works more on an incline, the lower part on decline presses.",{"clav":"Clavicular head (upper chest)","stern":"Sternocostal head (mid chest)","abd":"Abdominal head (lower chest)"}],"pec_minor":["Pectoralis minor","Deep chest muscle","Pulls the shoulder blade forward and down. Stabilises the shoulder blade in dips and presses. When tight it pulls the shoulders forward.",{"pm":"Pectoralis minor","subcl":"Subclavius"}],"serratus":["Serratus anterior","Serratus","Holds the shoulder blade against the ribcage and pushes it forward. Together with the trapezius it rotates the shoulder blade upward so the arm can go overhead.",{}],"intercostals":["Intercostal muscles","Intercostals","Move the ribs during breathing: the external ones help inhalation, the internal ones forced exhalation. They stabilise the ribcage when you hold your breath on heavy lifts.",{"ext":"External intercostals","int":"Internal intercostals"}],"deltoid":["Deltoid","Shoulders","Raises the arm: the front part forward, the middle part sideways, the rear part backward. Gives the shoulder its rounded shape.",{"front":"Anterior head (front delt)","side":"Lateral head (side delt)","rear":"Posterior head (rear delt)"}],"rotator_cuff":["Rotator cuff","Shoulder rotators","Four muscles that keep the head of the humerus centred in the shoulder joint. The supraspinatus starts abduction, the infraspinatus and teres minor rotate the arm outward, the subscapularis rotates it inward.",{"supra":"Supraspinatus","infra":"Infraspinatus","tminor":"Teres minor","subscap":"Subscapularis"}],"teres_major":["Teres major","Teres major","Pulls the arm down and back and inward, together with the latissimus dorsi. That is why it is called the \"lat's little helper\".",{}],"trapezius":["Trapezius","Traps","Moves and stabilises the shoulder blade: the upper part shrugs the shoulders, the middle part pulls them back, the lower part pulls them down and helps the arm go overhead.",{"upper":"Upper (descending) part","middle":"Middle (transverse) part","lower":"Lower (ascending) part"}],"lats":["Latissimus dorsi","Lats (\"wings\")","The biggest muscle of the back. Pulls the arm down and back (pull-ups, rows), rotates it inward and gives the torso its V shape.",{}],"rhomboids":["Rhomboids","Rhomboids","Pull the shoulder blades toward the spine and stabilise them during rows and presses.",{"major":"Rhomboid major","minor":"Rhomboid minor"}],"levator_scap":["Levator scapulae","Levator scapulae","Lifts the shoulder blade and bends the neck sideways. Often tight in people who sit for many hours in front of a screen.",{}],"erectors":["Erector spinae","Lower back","Three columns of muscle beside the spine. They extend the back and keep it straight, especially when you bend over with weight.",{"ilio":"Iliocostalis","long":"Longissimus","spin":"Spinalis"}],"multifidus":["Multifidus & transversospinalis","Deep spinal muscles","Small deep muscles between the vertebrae. They stabilise each vertebra individually and protect the lower back.",{"mf":"Multifidus","semi":"Semispinalis","rot":"Rotatores"}],"quadratus_lumb":["Quadratus lumborum","Quadratus lumborum","Bends the trunk sideways and keeps the pelvis level when you carry weight on one side.",{}],"scm":["Sternocleidomastoid","Front of the neck","Turns the head to the opposite side. When both work together they flex the head forward.",{}],"splenius":["Splenius","Back of the neck","Extends the neck and turns the head to the same side.",{"cap":"Splenius capitis","col":"Splenius cervicis"}],"scalenes":["Scalenes","Scalenes","Bend the neck sideways and lift the first two ribs during deep inhalation.",{"ant":"Anterior scalene","med":"Middle scalene","post":"Posterior scalene"}],"hyoid":["Hyoid muscles","Throat muscles","Move the hyoid bone and larynx during swallowing and speech, and help open the mouth.",{"infra":"Infrahyoid muscles","supra":"Suprahyoid muscles"}],"jaw":["Muscles of mastication","Jaw","Close the jaw and provide the force for chewing. The masseter is among the strongest muscles for its size.",{"masseter":"Masseter","temporalis":"Temporalis"}],"face":["Muscles of facial expression","Face","Produce facial expressions: smiling, frowning, closing the eyes and lips. They are not trained with weights.",{"frontalis":"Frontalis","occipitalis":"Occipitalis","temporopar":"Temporoparietalis","galea":"Galea aponeurotica","orb_oculi":"Orbicularis oculi","corrugator":"Corrugator supercilii","procerus":"Procerus","nasalis":"Nasalis","lev_lab_nasi":"Levator labii superioris alaeque nasi","lev_lab":"Levator labii superioris","zyg_minor":"Zygomaticus minor","zyg_major":"Zygomaticus major","lev_ang":"Levator anguli oris","risorius":"Risorius","buccinator":"Buccinator","orb_oris":"Orbicularis oris","dep_ang":"Depressor anguli oris","dep_lab":"Depressor labii inferioris","mentalis":"Mentalis"}],"biceps":["Biceps brachii","Biceps","Bends the elbow and turns the palm upward (supination). The long head also crosses the shoulder.",{"long":"Long head (outer)","short":"Short head (inner)"}],"brachialis":["Brachialis","Brachialis","The \"hidden\" elbow flexor beneath the biceps. It works in every curl, whatever the position of the palm.",{}],"coracobrachialis":["Coracobrachialis","Coracobrachialis","Brings the arm forward and inward. Helps in flyes and front raises.",{}],"triceps":["Triceps brachii","Triceps","Extends the elbow. The long head crosses the shoulder, so it works more when the arm is overhead.",{"long":"Long head","lat":"Lateral head","med":"Medial head"}],"brachioradialis":["Brachioradialis","Upper forearm","Bends the elbow, mainly when the palm faces inward (hammer grip).",{}],"forearm_flex":["Forearm flexors","Forearms (inner side)","Bend the wrist and fingers and provide grip strength. The pronators turn the palm downward.",{"fcr":"Flexor carpi radialis","pl":"Palmaris longus","fcu":"Flexor carpi ulnaris","pt":"Pronator teres","fds":"Flexor digitorum superficialis","fdp":"Flexor digitorum profundus","fpl":"Flexor pollicis longus","pq":"Pronator quadratus"}],"forearm_ext":["Forearm extensors","Forearms (outer side)","Extend the wrist and fingers and stabilise the wrist in every grip. The supinator turns the palm upward.",{"ecrl":"Extensor carpi radialis longus","ecrb":"Extensor carpi radialis brevis","ed":"Extensor digitorum","edm":"Extensor digiti minimi","ecu":"Extensor carpi ulnaris","anc":"Anconeus","apl":"Abductor pollicis longus","epb":"Extensor pollicis brevis","epl":"Extensor pollicis longus","ei":"Extensor indicis","sup":"Supinator"}],"hand":["Muscles of the hand","Palm","Produce the fine movements of the fingers and bring the thumb against the other fingers. They take part in every tight grip.",{"thenar":"Thenar (thumb muscles)","hypothenar":"Hypothenar (little finger muscles)","inter":"Interossei & lumbricals"}],"rectus_abd":["Rectus abdominis","Abs (six-pack)","Flexes the trunk (brings the chest toward the pelvis) and stabilises it during lifts. Its tendinous inscriptions create the six-pack look.",{"ra":"Rectus abdominis","pyr":"Pyramidalis"}],"ext_oblique":["External oblique","Side abs (obliques)","Rotates the trunk to the opposite side, bends it sideways and resists rotation.",{}],"int_oblique":["Internal oblique","Deep side abs","Lies beneath the external oblique. Rotates the trunk to the same side and helps with stabilisation.",{}],"transversus":["Transversus abdominis","Deep abs (\"corset\")","The deepest abdominal muscle. Works like a natural belt: increases pressure inside the abdomen and stabilises the lower back before every movement.",{}],"iliopsoas":["Iliopsoas","Hip flexors","The strongest hip flexor: lifts the knee toward the chest and brings the trunk toward the legs.",{"psoas":"Psoas major","iliacus":"Iliacus"}],"glute_max":["Gluteus maximus","Glutes","Extends the hip (drives the pelvis forward) and rotates the thigh outward. The main muscle in climbing stairs, running and hip thrusts.",{}],"glute_med":["Gluteus medius","Side glutes","Abducts the thigh and keeps the pelvis level when you stand on one leg (walking, running, lunges).",{}],"glute_min":["Gluteus minimus","Deep glute","Lies beneath the gluteus medius and assists it in abduction and hip stabilisation.",{}],"tfl":["Tensor fasciae latae","TFL & IT band","Abducts and flexes the hip and tenses the iliotibial band, which stabilises the knee from the outside.",{"tfl":"Tensor fasciae latae","it":"Iliotibial band (IT band)"}],"hip_rotators":["Lateral rotators of the hip","Piriformis & deep rotators","Rotate the thigh outward and centre the head of the femur in the hip socket.",{"pir":"Piriformis","gem":"Gemelli","oi":"Obturator internus","oe":"Obturator externus","qf":"Quadratus femoris"}],"quads":["Quadriceps femoris","Quads","Extends the knee. The rectus femoris also crosses the hip and helps flex it.",{"rf":"Rectus femoris","vl":"Vastus lateralis","vm":"Vastus medialis (\"teardrop\")","vi":"Vastus intermedius"}],"sartorius":["Sartorius","Sartorius","The longest muscle in the body. Flexes, abducts and externally rotates the hip and flexes the knee (the \"tailor's position\").",{}],"adductors":["Adductors","Inner thighs","Bring the thighs inward. The adductor magnus also helps extend the hip in squats and lifts.",{"longus":"Adductor longus","magnus":"Adductor magnus","grac":"Gracilis","pect":"Pectineus","brevis":"Adductor brevis"}],"hamstrings":["Hamstrings","Hamstrings","Bend the knee and extend the hip. They work hard in Romanian deadlifts and leg curls.",{"bfl":"Biceps femoris – long head","bfs":"Biceps femoris – short head","st":"Semitendinosus","sm":"Semimembranosus"}],"calves":["Triceps surae","Calves","Raise the heel (plantar flexion). The gastrocnemius works more with a straight knee, the soleus with a bent knee.",{"gm":"Gastrocnemius – medial head","gl":"Gastrocnemius – lateral head","sol":"Soleus","plant":"Plantaris","achilles":"Achilles tendon"}],"tib_ant":["Tibialis anterior & extensors","Front of the lower leg (shins)","Lift the toes and the foot toward the shin (dorsiflexion) and brake the foot at every step.",{"ta":"Tibialis anterior","edl":"Extensor digitorum longus","ehl":"Extensor hallucis longus","ft":"Fibularis tertius"}],"fibularis":["Fibularis (peroneal) muscles","Outer lower leg","Turn the sole outward (eversion) and protect the ankle from sprains.",{"fl":"Fibularis longus","fb":"Fibularis brevis"}],"deep_calf":["Deep posterior leg muscles","Deep calf","Support the arch of the foot and flex the toes. The popliteus \"unlocks\" the straightened knee.",{"tp":"Tibialis posterior","fdl":"Flexor digitorum longus","fhl":"Flexor hallucis longus","pop":"Popliteus"}],"foot":["Muscles of the foot","Sole of the foot","Support the arch and move the toes. Important for balance and running.",{"dorsal":"Dorsal muscles","plantar":"Plantar muscles","inter":"Interossei"}]};
